CREATE POLICY contract_finance_read ON storage.objects FOR SELECT TO authenticated USING(bucket_id='contract-documents' AND public.finance_can_read());
CREATE POLICY contract_finance_upload ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='contract-documents' AND (public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'accountant')) AND (storage.foldername(name))[1]=auth.uid()::text);
CREATE POLICY accountant_proof_read ON storage.objects FOR SELECT TO authenticated USING(bucket_id='unit-collection-proofs' AND public.finance_can_read());
CREATE POLICY accountant_proof_upload ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='unit-collection-proofs' AND public.has_role(auth.uid(),'accountant') AND (storage.foldername(name))[1]=auth.uid()::text);
CREATE OR REPLACE FUNCTION public.resolve_legacy_receipt(_source uuid,_resolution text,_reason text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE s public.receipt_legacy_sources; BEGIN PERFORM public.finance_assert_writer(); PERFORM public._assert_reason(_reason); IF _resolution NOT IN ('distinct','duplicate') THEN RAISE EXCEPTION 'قرار المراجعة غير صالح'; END IF; SELECT * INTO s FROM public.receipt_legacy_sources WHERE id=_source FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'المصدر غير موجود'; END IF; IF s.resolution<>'review' THEN RAISE EXCEPTION 'تمت مراجعة المصدر مسبقًا'; END IF; UPDATE public.receipt_legacy_sources SET resolution=_resolution,resolution_reason=_reason,resolved_by=auth.uid(),resolved_at=now() WHERE id=s.id; PERFORM public.finance_audit('LEGACY_SOURCE_REVIEWED','receipt_legacy_sources',s.id,to_jsonb(s),(SELECT to_jsonb(x) FROM public.receipt_legacy_sources x WHERE id=s.id),_reason); END $$;
REVOKE ALL ON FUNCTION public.resolve_legacy_receipt(uuid,text,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.resolve_legacy_receipt(uuid,text,text) TO authenticated;
CREATE OR REPLACE FUNCTION public.enable_finance_cutover(_reason text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN PERFORM public.finance_assert_writer(); PERFORM public._assert_reason(_reason); IF EXISTS(SELECT 1 FROM public.receipt_legacy_sources WHERE resolution='review') OR EXISTS(SELECT 1 FROM public.receipt_reconciliation WHERE unexplained_difference<>0) THEN RAISE EXCEPTION 'اعتماد النقل موقوف؛ راجع المصادر والفروق أولًا'; END IF; RAISE EXCEPTION 'التحويل النهائي غير متاح قبل اكتمال ربط جميع مسارات النظام؛ السجلات القديمة محفوظة'; END $$;
REVOKE ALL ON FUNCTION public.enable_finance_cutover(text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.enable_finance_cutover(text) TO authenticated;
SELECT source_table,sum(unexplained_difference) AS unexplained_difference FROM public.receipt_reconciliation GROUP BY source_table;